public class Main {
static void validateAge(int age) {
    if (age < 0) throw new IllegalArgumentException("age must be non-negative");
}
    public static void main(String[] args) {
        try {
            validateAge(-1);
        } catch (IllegalArgumentException ex) {
            System.out.println(ex.getMessage());
        }
    }
}
